"""ex07 错误可行动化：把异常包装成 LLM 能据以决策的提示。"""


class ToolError(Exception):
    def __init__(self, code, message, retryable, hint):
        super().__init__(message)
        self.code = code
        self.message = message
        self.retryable = retryable
        self.hint = hint


RAW_FAILURES = [
    (KeyError("city"), "get_weather", {"unit": "c"}),
    (TimeoutError("upstream timeout after 5s"), "search_web", {"q": "x"}),
    (PermissionError("token lacks scope: write"), "send_email", {"to": "a@b.c"}),
    (ValueError("days must be <= 7"), "get_weather", {"city": "Beijing", "days": 30}),
]


def to_actionable(exc, tool, args):
    """异常 -> {code, retryable, message, hint} 四要素。"""
    if isinstance(exc, KeyError):
        missing = str(exc).strip("'")
        return ToolError("MISSING_PARAM", "缺少必填参数 %s" % missing, False,
                         "请补齐参数 %s 后重新调用 %s" % (missing, tool))
    if isinstance(exc, TimeoutError):
        return ToolError("UPSTREAM_TIMEOUT", "下游超时", True,
                         "可原样重试；连续 3 次超时则改用备用数据源或升级给人")
    if isinstance(exc, PermissionError):
        return ToolError("PERMISSION_DENIED", "凭据缺少写权限", False,
                         "不要重试；该操作需人工授权或改用只读工具")
    if isinstance(exc, ValueError):
        return ToolError("INVALID_ARG", "参数越界：%s" % exc, False,
                         "修正参数取值后重新调用，或向用户澄清")
    return ToolError("UNKNOWN", str(exc), True, "保留现场日志后重试一次")


def render(tool, args, err):
    return ("工具 %s 调用失败\n  code      = %s\n  retryable = %s\n"
            "  message   = %s\n  hint      = %s\n  args      = %s"
            % (tool, err.code, err.retryable, err.message, err.hint, args))


if __name__ == "__main__":
    retryable_n = 0
    for exc, tool, args in RAW_FAILURES:
        err = to_actionable(exc, tool, args)
        if err.retryable:
            retryable_n += 1
        print(render(tool, args, err))
        print("  下一步建议动作: %s"
              % ("重试同一调用" if err.retryable else "不重试，改为修正参数或升级给人"))
        print()
    print("可重试错误 = %d / 不可重试错误 = %d"
          % (retryable_n, len(RAW_FAILURES) - retryable_n))
